/* Query LLAC pre/post rotations for verified hosts/standard lengths, otherwise return null. */
const Complex *v4_llac_dct4_rotations(int32_t length) {
#if LHDC_PLATFORM_FIXED_DSP_TABLES
    switch (length) {
    case 20:
        return llac_dct4_rotations_20;
    case 40:
        return llac_dct4_rotations_40;
    case 60:
        return llac_dct4_rotations_60;
    case 80:
        return llac_dct4_rotations_80;
    case 110:
        return llac_dct4_rotations_110;
    case 120:
        return llac_dct4_rotations_120;
    case 160:
        return llac_dct4_rotations_160;
    case 220:
        return llac_dct4_rotations_220;
    case 240:
        return llac_dct4_rotations_240;
    case 320:
        return llac_dct4_rotations_320;
    case 440:
        return llac_dct4_rotations_440;
    case 480:
        return llac_dct4_rotations_480;
    case 960:
        return llac_dct4_rotations_960;
    default:
        return NULL;
    }
#else
    (void)length;
    return NULL;
#endif
}
